# surrounding blanks", "must not contain '::'").
function Get-IdentityStringProblem {
    param($Value)
    if (-not ($Value -is [string]) -or -not $Value.Trim()) { return 'is empty' }
    if ($Value -cne $Value.Trim()) { return 'has surrounding blanks' }
